.sqs-audio-player :focus { outline-color: rgb(255, 255, 255) !important; }

.sqs-audio-player :focus:not(:focus-visible) { outline-color: transparent !important; }

.sqs-audio-player.download .sqs-audio-player-content { padding-right: 189px; }

.sqs-audio-player.download .volume { right: 75px; }

.sqs-audio-player.download .duration { right: 113px; }

