.sqs-audio-player .controls:hover, .sqs-audio-player .controls:focus { opacity: 1; }

.sqs-audio-player.error .placeholder { color: rgb(238, 238, 238); margin-left: 18px; }

.sqs-audio-player.error .controls, .sqs-audio-player.error .volume, .sqs-audio-player.play-state-stopped .progress, .sqs-audio-player.play-state-stopped .duration { display: none; }

